WITH rollup_totals AS (SELECT p.account_type, a.merchant, COUNT(*) AS cnt, ROUND(AVG(a.amount), 2) AS avg_amount FROM transactions a INNER JOIN accounts p ON a.account_id = p.id GROUP BY CUBE (p.account_type, a.merchant)) SELECT account_type, merchant, cnt, avg_amount, CASE WHEN merchant RLIKE '^(Starbucks|Lazada)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS merchant_zone FROM rollup_totals ORDER BY merchant;
